1	use std::any::Any;
2	use std::fmt;
3	
4	use super::request::GenerateRequest;
5	
6	/// A request's KV-prefix resolution, produced by the KV store *before* the
7	/// request reaches a scheduler: how many leading prompt tokens are already
8	/// materialized in the target rank's GPU prefix cache, plus an opaque RAII
9	/// hold keeping those blocks resident until the scheduler's prefix match
10	/// consumes them.
11	///
12	/// The engine contract deliberately does not know KV internals (this crate is
13	/// CUDA-free): the hold is minted by `pegainfer-kv-store`, carried opaquely,
14	/// and only ever *dropped* — after the scheduler's `match_and_add_prefix`, or
15	/// with the request if it dies first. Dropping releases the anti-eviction pin.
16	///
17	/// Degraded resolutions (timeout, pool pressure) are not a distinct state:
18	/// they surface as a smaller `hit_tokens` — the number alone carries all
19	/// downstream semantics (disaggregated-decode admission asserts it against
20	/// the handoff's committed length; everyone else just prefills from
21	/// `hit_tokens`).
22	pub struct KvPrefix {
23	    hit_tokens: usize,
24	    hold: Option<Box<dyn Any + Send>>,
25	    /// The scheduler partition the resolution ran against. The hold pins
26	    /// blocks on THIS rank, so routing anywhere else silently loses the hit
27	    /// and wastes the pin — [`crate::engine::EngineHandle::submit_resolved`]
28	    /// routes by it.
29	    rank: Option<usize>,
30	}
31	
32	impl KvPrefix {
33	    /// No resolution ran (or it degraded to nothing): prefill from scratch.
34	    /// The scheduler's own GPU prefix match still applies as usual.
35	    #[must_use]
36	    pub fn none() -> Self {
37	        Self {
38	            hit_tokens: 0,
39	            hold: None,
40	            rank: None,
41	        }
42	    }
43	
44	    /// A resolved prefix: `hit_tokens` are materialized on partition `rank`,
45	    /// pinned by `hold` until this value is dropped.
46	    #[must_use]
47	    pub fn resolved(hit_tokens: usize, rank: usize, hold: Box<dyn Any + Send>) -> Self {
48	        Self {
49	            hit_tokens,
50	            hold: Some(hold),
51	            rank: Some(rank),
52	        }
53	    }
54	
55	    pub fn hit_tokens(&self) -> usize {
56	        self.hit_tokens
57	    }
58	
59	    /// The partition the resolution is bound to, if one ran.
60	    pub(crate) fn rank(&self) -> Option<usize> {
61	        self.rank
62	    }
63	
64	    /// Whether a hold is still pinning resolved blocks.
65	    pub fn has_hold(&self) -> bool {
66	        self.hold.is_some()
67	    }
68	
69	    /// The opaque hold, for the store that minted it to downcast. Every
70	    /// other crate treats the hold as drop-only.
71	    pub fn hold_any(&self) -> Option<&(dyn Any + Send)> {
72	        self.hold.as_deref()
73	    }
74	}
75	
76	impl fmt::Debug for KvPrefix {
77	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
78	        f.debug_struct("KvPrefix")
79	            .field("hit_tokens", &self.hit_tokens)
80	            .field("rank", &self.rank)
81	            .field("hold", &self.hold.as_ref().map(|_| "<opaque>"))
82	            .finish()
83	    }
84	}
85	
86	/// What a scheduler partition's submit channel carries: the request plus its
87	/// KV-prefix resolution. Unresolved paths submit [`KvPrefix::none`]; the
88	/// tuple (rather than a wrapper struct) states the fact plainly — the store's
89	/// output is a prefix resolution, not a new kind of request.
90	pub type SubmittedRequest = (GenerateRequest, KvPrefix);
91	
92	/// KV pool capacity as the scheduler actually allocates it: whole blocks of
93	/// `block_size` tokens. A request of `L` tokens occupies `⌈L / block_size⌉`
94	/// blocks no matter how `L` divides, so a fit check must round per request —
95	/// summing raw token counts under-counts and can admit a batch that the
96	/// scheduler then has to defer. Lets a caller (e.g. the prefill/decode bench)
97	/// decide up front whether a batch fits without computing per-token KV by hand.
98	#[derive(Clone, Copy, Debug)]
99	pub struct KvCapacity {
100	    /// Blocks available for requests when the pool is empty.
101	    pub total_blocks: usize,
102	    /// Tokens per block.
103	    pub block_size: usize,
104	}
105	
106	impl KvCapacity {
107	    /// Total tokens the pool can hold (`total_blocks × block_size`).
108	    #[must_use]
109	    pub(crate) fn total_tokens(self) -> usize {
110	        self.total_blocks.saturating_mul(self.block_size)
111	    }
112	
113	    /// Blocks a single request of `tokens` tokens occupies — whole-block
114	    /// allocation rounds up.
115	    #[must_use]
116	    pub fn blocks_for(self, tokens: usize) -> usize {
117	        tokens.div_ceil(self.block_size.max(1))
118	    }
119	}
120

