202	    /// Submit a request together with its KV-prefix resolution. Routing is by
203	    /// the request's `data_parallel_rank` (unbound requests go to the
204	    /// least-loaded partition), so the caller that resolved the prefix must
205	    /// have bound the request to the rank it resolved against.
206	    #[allow(clippy::result_large_err)]
207	    fn submit_resolved(
208	        &self,
209	        req: GenerateRequest,
210	        kv_prefix: KvPrefix,
211	    ) -> std::result::Result<(), mpsc::error::SendError<GenerateRequest>> {
212	        // A resolved prefix binds the request: its hold pins blocks on
213	        // the rank it resolved against, so that rank wins the routing.
214	        // A caller-bound rank that disagrees is a caller bug.
215	        let partition = match (kv_prefix.rank(), req.data_parallel_rank) {
216	            (Some(resolved), bound) => {
217	                debug_assert!(
218	                    bound.is_none_or(|b| b == resolved),
219	                    "request bound to rank {bound:?} but its prefix resolved on rank {resolved}"
220	                );
221	                resolved
222	            }
223	            (None, Some(bound)) => bound,
224	            (None, None) => self.least_loaded_partition(),
225	        };
