239	    /// waiting-weighted load (`running + 4 × waiting`, the same weight the
240	    /// vLLM DP load balancer uses), ties to the lowest index. Scores come
241	    /// from the partitions' load watches; a partition without a feed scores
242	    /// zero, so the single-partition degenerate always returns 0.
243	    fn least_loaded_partition(&self) -> usize {
244	        self.inner
245	            .submit_txs
246	            .iter()
247	            .enumerate()
248	            .min_by_key(|(partition, _)| {
249	                let score = self
250	                    .metrics_watches
251	                    .get(*partition)
252	                    .and_then(Option::as_ref)
253	                    .map_or(0, |watch| {
254	                        let snapshot = watch.borrow();
255	                        snapshot.num_running_reqs + 4 * snapshot.num_waiting_reqs
256	                    });
257	                (score, *partition)
258	            })
259	            .map_or(0, |(partition, _)| partition)
260	    }
261	}
