271	/// Answer a request the handle cannot place (a `data_parallel_rank` outside
272	/// the engine's partition topology) with the standard Scheduled → Rejected
273	/// pair — the same surface a model scheduler's admission rejection produces.
274	fn reject_unroutable(req: &GenerateRequest, partition: usize, partitions: usize) {
275	    let queued_at_unix_s = req.queued_at_unix_s.unwrap_or_else(unix_now_s);
276	    let _ = req.token_tx.send(TokenEvent::Scheduled {
277	        queued_at_unix_s,
278	        scheduled_at_unix_s: unix_now_s(),
279	        prompt_tokens: req.prompt_tokens.len(),
280	        cached_tokens: 0,
281	    });
282	    let _ = req.token_tx.send(TokenEvent::Rejected {
283	        message: format!("data_parallel_rank {partition} is outside 0..{partitions}"),
284	        prompt_tokens: req.prompt_tokens.len(),
285	        completion_tokens: 0,
286	    });
287	}
