289	impl Drop for EngineInner {
290	    fn drop(&mut self) {
291	        self.submit_txs.clear();
292	        for join_handle in self.join_handles.drain(..) {
293	            if join_handle.thread().id() != thread::current().id() {
294	                if let Err(panic) = join_handle.join() {
295	                    log::warn!(
296	                        "engine thread panicked during shutdown: {}",
297	                        panic_message(panic.as_ref())
298	                    );
299	                }
300	            }
301	        }
302	    }
303	}
